import React, { useState } from 'react';
import { useTheme } from '../../contexts/ThemeContext';

interface CustomerFormData {
  nome: string;
  idade: string;
  cpf: string;
  telefone: string;
  email: string;
  endereco: string;
}

const CadastrarCliente: React.FC = () => {
  const { theme } = useTheme();
  const [formData, setFormData] = useState<CustomerFormData>({
    nome: '',
    idade: '',
    cpf: '',
    telefone: '',
    email: '',
    endereco: ''
  });
  const [errors, setErrors] = useState<Partial<CustomerFormData>>({});
  const [isLoading, setIsLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');

  const validateForm = (): boolean => {
    const newErrors: Partial<CustomerFormData> = {};

    if (!formData.nome.trim()) {
      newErrors.nome = 'Nome é obrigatório';
    }

    if (!formData.idade.trim()) {
      newErrors.idade = 'Idade é obrigatória';
    } else if (isNaN(Number(formData.idade)) || Number(formData.idade) < 0 || Number(formData.idade) > 120) {
      newErrors.idade = 'Idade deve ser um número válido entre 0 e 120';
    }

    if (!formData.cpf.trim()) {
      newErrors.cpf = 'CPF é obrigatório';
    } else if (!/^\d{11}$/.test(formData.cpf.replace(/\D/g, ''))) {
      newErrors.cpf = 'CPF deve conter 11 dígitos';
    }

    if (!formData.telefone.trim()) {
      newErrors.telefone = 'Telefone é obrigatório';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email é obrigatório';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Email inválido';
    }

    if (!formData.endereco.trim()) {
      newErrors.endereco = 'Endereço é obrigatório';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // Clear error for this field when user starts typing
    if (errors[name as keyof CustomerFormData]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const formatCPF = (value: string) => {
    const digits = value.replace(/\D/g, '');
    return digits
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');
  };

  const formatTelefone = (value: string) => {
    const digits = value.replace(/\D/g, '');
    return digits
      .replace(/(\d{2})(\d)/, '($1) $2')
      .replace(/(\d{5})(\d)/, '$1-$2')
      .replace(/(-\d{4})\d+?$/, '$1');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setIsLoading(true);
    setSuccessMessage('');

    try {
      // Simulação de API call
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      console.log('Cliente cadastrado:', formData);
      setSuccessMessage('Cliente cadastrado com sucesso!');
      
      // Reset form
      setFormData({
        nome: '',
        idade: '',
        cpf: '',
        telefone: '',
        email: '',
        endereco: ''
      });
      
    } catch (error) {
      console.error('Erro ao cadastrar cliente:', error);
      setErrors({ nome: 'Erro ao cadastrar cliente. Tente novamente.' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="card">
        <div className="mb-6">
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Cadastrar Cliente</h2>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Preencha os dados do novo cliente
          </p>
        </div>

        {successMessage && (
          <div className="mb-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 text-green-600 dark:text-green-400 px-4 py-3 rounded-lg">
            {successMessage}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Nome */}
            <div className="md:col-span-2">
              <label htmlFor="nome" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Nome Completo *
              </label>
              <input
                type="text"
                id="nome"
                name="nome"
                value={formData.nome}
                onChange={handleInputChange}
                className={`input-field ${errors.nome ? 'border-red-300 dark:border-red-700' : ''}`}
                placeholder="Digite o nome completo do cliente"
                disabled={isLoading}
              />
              {errors.nome && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.nome}</p>
              )}
            </div>

            {/* Idade */}
            <div>
              <label htmlFor="idade" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Idade *
              </label>
              <input
                type="number"
                id="idade"
                name="idade"
                value={formData.idade}
                onChange={handleInputChange}
                className={`input-field ${errors.idade ? 'border-red-300 dark:border-red-700' : ''}`}
                placeholder="Ex: 25"
                min="0"
                max="120"
                disabled={isLoading}
              />
              {errors.idade && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.idade}</p>
              )}
            </div>

            {/* CPF */}
            <div>
              <label htmlFor="cpf" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                CPF *
              </label>
              <input
                type="text"
                id="cpf"
                name="cpf"
                value={formData.cpf}
                onChange={(e) => {
                  const formatted = formatCPF(e.target.value);
                  handleInputChange({ ...e, target: { ...e.target, name: 'cpf', value: formatted } });
                }}
                className={`input-field ${errors.cpf ? 'border-red-300 dark:border-red-700' : ''}`}
                placeholder="000.000.000-00"
                maxLength={14}
                disabled={isLoading}
              />
              {errors.cpf && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.cpf}</p>
              )}
            </div>

            {/* Telefone */}
            <div>
              <label htmlFor="telefone" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Telefone *
              </label>
              <input
                type="tel"
                id="telefone"
                name="telefone"
                value={formData.telefone}
                onChange={(e) => {
                  const formatted = formatTelefone(e.target.value);
                  handleInputChange({ ...e, target: { ...e.target, name: 'telefone', value: formatted } });
                }}
                className={`input-field ${errors.telefone ? 'border-red-300 dark:border-red-700' : ''}`}
                placeholder="(00) 00000-0000"
                maxLength={15}
                disabled={isLoading}
              />
              {errors.telefone && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.telefone}</p>
              )}
            </div>

            {/* Email */}
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Email *
              </label>
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleInputChange}
                className={`input-field ${errors.email ? 'border-red-300 dark:border-red-700' : ''}`}
                placeholder="cliente@exemplo.com"
                disabled={isLoading}
              />
              {errors.email && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.email}</p>
              )}
            </div>

            {/* Endereço */}
            <div className="md:col-span-2">
              <label htmlFor="endereco" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Endereço Completo *
              </label>
              <textarea
                id="endereco"
                name="endereco"
                value={formData.endereco}
                onChange={handleInputChange}
                rows={3}
                className={`input-field resize-none ${errors.endereco ? 'border-red-300 dark:border-red-700' : ''}`}
                placeholder="Rua, número, bairro, cidade, estado, CEP"
                disabled={isLoading}
              />
              {errors.endereco && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.endereco}</p>
              )}
            </div>
          </div>

          <div className="flex justify-end space-x-4 pt-4">
            <button
              type="button"
              onClick={() => {
                setFormData({
                  nome: '',
                  idade: '',
                  cpf: '',
                  telefone: '',
                  email: '',
                  endereco: ''
                });
                setErrors({});
                setSuccessMessage('');
              }}
              className="btn-secondary"
              disabled={isLoading}
            >
              Limpar
            </button>
            <button
              type="submit"
              className="btn-primary"
              disabled={isLoading}
            >
              {isLoading ? (
                <span className="flex items-center">
                  <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Cadastrando...
                </span>
              ) : (
                'Cadastrar Cliente'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CadastrarCliente;
